const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const lakeElton = ee.Geometry.Point([46.7, 49.22]);
    const aoi = lakeElton.buffer(5000); // 5km buffer to cover a good portion of the salt lake

    const startYear1 = 2004;
    const startYear2 = 2009;
    const summerStart = '-06-01';
    const summerEnd = '-09-30';

    const dateRange1 = ee.DateRange(startYear1 + summerStart, startYear1 + summerEnd);
    const dateRange2 = ee.DateRange(startYear2 + summerStart, startYear2 + summerEnd);

    // 2. Data Acquisition & Processing Logic
    const l5sr = 'LANDSAT/LT05/C02/T1_L2';

    // Function to mask clouds, shadow, and snow using the QA_PIXEL band
    function maskL457sr(image) {
        // Bit 0 - Fill
        // Bit 1 - Dilated Cloud
        // Bit 3 - Cloud
        // Bit 4 - Cloud Shadow
        // Bit 5 - Snow
        const qa = image.select('QA_PIXEL');
        const cloudShadow = qa.bitwiseAnd(1 << 4).neq(0);
        const cloud = qa.bitwiseAnd(1 << 3).neq(0).or(qa.bitwiseAnd(1 << 1).neq(0));
        const snow = qa.bitwiseAnd(1 << 5).neq(0);
        const mask = cloud.or(cloudShadow).or(snow);
        return image.updateMask(mask.not());
    }

    // Function to scale bands and calculate average reflectance
    function processImage(image) {
        const opticalBands = image.select(['SR_B1', 'SR_B2', 'SR_B3', 'SR_B4']);
        // Apply scaling factors
        const scaledBands = opticalBands.multiply(0.0000275).add(-0.2);
        // Calculate the average of the first four bands as a proxy for overall reflectance
        const avgReflectance = scaledBands.reduce(ee.Reducer.mean()).rename('avg_reflectance');
        return scaledBands.addBands(avgReflectance);
    }

    // Get data for the first period
    const collection1 = ee.ImageCollection(l5sr)
        .filterBounds(aoi)
        .filterDate(dateRange1);

    const size1 = collection1.size().getInfo();
    if (size1 === 0) {
        console.log(`No images found for ${startYear1}.`);
        console.log("A: No");
        return;
    }

    const image1 = collection1.map(maskL457sr).map(processImage).median().clip(aoi);

    // Get data for the second period
    const collection2 = ee.ImageCollection(l5sr)
        .filterBounds(aoi)
        .filterDate(dateRange2);

    const size2 = collection2.size().getInfo();
    if (size2 === 0) {
        console.log(`No images found for ${startYear2}.`);
        console.log("C1: Empty Collection");
        return;
    }

    const image2 = collection2.map(maskL457sr).map(processImage).median().clip(aoi);

    // 3. Calculation
    const reducers = ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
    });

    const stats1 = image1.select('avg_reflectance').reduceRegion({
        reducer: reducers,
        geometry: aoi,
        scale: 1000,
        maxPixels: 1e9
    });

    const stats2 = image2.select('avg_reflectance').reduceRegion({
        reducer: reducers,
        geometry: aoi,
        scale: 1000,
        maxPixels: 1e9
    });

    // 4. Validation & Final Answer
    const val1 = stats1.get('avg_reflectance_mean').getInfo();
    const count1 = stats1.get('avg_reflectance_count').getInfo();

    const val2 = stats2.get('avg_reflectance_mean').getInfo();
    const count2 = stats2.get('avg_reflectance_count').getInfo();

    console.log(`${startYear1} Images Found: ${size1}`);
    console.log(`${startYear1} Reflectance: ${val1 !== null ? val1.toFixed(4) : 'N/A'}, Valid Pixels: ${count1}`);
    console.log(`${startYear2} Images Found: ${size2}`);
    console.log(`${startYear2} Reflectance: ${val2 !== null ? val2.toFixed(4) : 'N/A'}, Valid Pixels: ${count2}`);

    if (count1 === 0 || count2 === 0) {
        console.log("No valid pixels after cloud masking for one or both periods.");
        console.log("C2: No Valid Pixels");
        return;
    }

    if (val1 === null || val2 === null) {
        console.log("Calculation failed, result is null.");
        console.log("C3: Calculation Failure");
        return;
    }

    if (val2 > val1) {
        console.log("A: Yes");
    } else {
        console.log("B: No");
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(err => {
    console.error("An error occurred: ", err);
    console.log("D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.");
});
